/**
 * AI orchestrator — routes calls through the priority chain:
 *
 *   1. Client-side AI (BYOK) — if user has configured providers
 *   2. Convex server action — the existing server-side path
 *   3. Local deterministic fallback — always works, no network
 *
 * All panels import this instead of calling Convex actions directly,
 * so BYOK is transparently enabled everywhere.
 */

import type { AiSettings, AiFeature } from "../types";
import { loadAiSettingsFromIdb } from "./idb";
import {
  hasConfiguredAiProvider,
  runClientAgent,
  normalizeAiSettings,
} from "./ai-client";
import type { AgentRequest, AgentResponse } from "../../convex/agentPrompts";
import type { ConvexClient } from "convex/browser";
import { reportApplicationDiagnostic } from "./application-diagnostics";

/* ── Cached settings ────────────────────────────────────────────── */

let _cachedSettings: AiSettings | null = null;

export async function getCachedAiSettings(): Promise<AiSettings> {
  if (_cachedSettings) return _cachedSettings;
  const raw = await loadAiSettingsFromIdb();
  _cachedSettings = normalizeAiSettings(raw);
  return _cachedSettings;
}

export function invalidateAiSettingsCache(): void {
  _cachedSettings = null;
}

// Settings saved on the Settings route must reach the features immediately.
// Without this the memo above outlives the save and the writer's new key is
// ignored until a full reload — the voice features fail loudest, since their
// only fallback is a hosted, account-gated path.
if (
  typeof window !== "undefined" &&
  typeof window.addEventListener === "function"
) {
  window.addEventListener("twyne:ai-settings-saved", invalidateAiSettingsCache);
}

/* ── Convenience: run with full fallback chain ──────────────────── */

export interface OrchestratorOptions {
  feature: AiFeature;
  req: AgentRequest;
  client: ConvexClient | null;
  serverAction?: () => Promise<AgentResponse>;
  localFallback?: () => AgentResponse;
}

export async function runAiWithFallback(
  opts: OrchestratorOptions,
): Promise<AgentResponse> {
  // 1. Try client-side AI
  const settings = await getCachedAiSettings();
  if (hasConfiguredAiProvider(settings)) {
    const clientResult = await runClientAgent(opts.feature, opts.req, settings);
    if (clientResult) {
      // Tag with "client" prefix so UI can distinguish
      return {
        ...clientResult,
        provider:
          `client-${clientResult.provider}` as AgentResponse["provider"],
      };
    }
  }

  // 2. Try server action
  if (opts.serverAction) {
    try {
      return await opts.serverAction();
    } catch (err) {
      reportApplicationDiagnostic(
        `twyne:ai-orchestrator:${opts.feature}`,
        err,
        { feature: opts.feature },
      );
    }
  }

  // 3. Local fallback
  if (opts.localFallback) {
    return opts.localFallback();
  }

  // Ultimate fallback — should never reach here if localFallback is provided
  return {
    text: "The room is quiet. Try again when connected.",
    type: "perspective",
    provider: "local",
  };
}

import { normalizeApplicationError } from "./application-errors";
import { capturePostHogEvent } from "./posthog-context";

export function shouldLogRawDiagnostics(): boolean {
  return typeof import.meta !== "undefined" && Boolean(import.meta.env?.DEV);
}

/**
 * Preserve raw diagnostics during development, but never echo provider,
 * Convex, prompt, transcript, or draft details in a production console.
 */
export function reportApplicationDiagnostic(
  scope: string,
  thrown: unknown,
  metadata?: Record<string, unknown>,
): void {
  if (shouldLogRawDiagnostics()) {
    console.warn(scope, thrown);
    return;
  }
  const error = normalizeApplicationError(thrown, { metadata });
  void capturePostHogEvent("$exception", {
    distinct_id: "twyne-browser",
    $exception_type: "ApplicationError",
    $exception_message: error.message,
    $exception_is_unhandled: false,
    $level: "error",
    twyne_error_code: error.code,
    twyne_error_reference_id: error.referenceId,
    twyne_error_source: error.source,
    twyne_error_scope: scope,
    ...error.metadata,
  });
}
